// ListThirdParties reads every third-party record the filter keeps.
func ListThirdParties(sandbox *api.Sandbox, self *ErpDb, filter ThirdPartyFilter) ([]ThirdPartyRecord, error) {
	collection, err := sandbox.Deps.OpinionatedAgnosDatabase.Collection(self.database, "third-party")
	if err != nil {
		return nil, err
	}
	records, failure := collection.ListAll()
	if failure != nil {
		return nil, sandbox.Deps.OpinionatedAgnosDatabase.Fail(failure)
	}
	kept := []ThirdPartyRecord{}
	for _, record := range records {
		built, err := buildThirdPartyRecord(sandbox, record)
		if err != nil {
			return nil, err
		}
		if !matchThirdParty(sandbox, built, filter) {
			continue
		}
		kept = append(kept, built)
	}
	return kept, nil
}

