// ListTransactions reads every transaction record the filter keeps.
func ListTransactions(sandbox *api.Sandbox, self *ErpDb, filter TransactionFilter) ([]TransactionRecord, error) {
	collection, err := sandbox.Deps.OpinionatedAgnosDatabase.Collection(self.database, "transaction")
	if err != nil {
		return nil, err
	}
	records, failure := collection.ListAll()
	if failure != nil {
		return nil, sandbox.Deps.OpinionatedAgnosDatabase.Fail(failure)
	}
	kept := []TransactionRecord{}
	for _, record := range records {
		built, err := buildTransactionRecord(sandbox, record)
		if err != nil {
			return nil, err
		}
		if !matchTransaction(sandbox, built, filter) {
			continue
		}
		kept = append(kept, built)
	}
	return kept, nil
}

// ListTransactionsPage reads up to limit transaction records after the first offset, every one past them when limit is 0.
func ListTransactionsPage(sandbox *api.Sandbox, self *ErpDb, offset int, limit int) ([]TransactionRecord, error) {
	collection, err := sandbox.Deps.OpinionatedAgnosDatabase.Collection(self.database, "transaction")
	if err != nil {
		return nil, err
	}
	records, failure := collection.List(offset+1, limit)
	if failure != nil {
		return nil, sandbox.Deps.OpinionatedAgnosDatabase.Fail(failure)
	}
	page := []TransactionRecord{}
	for _, record := range records {
		built, err := buildTransactionRecord(sandbox, record)
		if err != nil {
			return nil, err
		}
		page = append(page, built)
	}
	return page, nil
}

// CountTransaction is how many transaction records are live.
func CountTransaction(sandbox *api.Sandbox, self *ErpDb) (int, error) {
	collection, err := sandbox.Deps.OpinionatedAgnosDatabase.Collection(self.database, "transaction")
	if err != nil {
		return 0, err
	}
	records, failure := collection.ListAll()
	if failure != nil {
		return 0, sandbox.Deps.OpinionatedAgnosDatabase.Fail(failure)
	}
	return len(records), nil
}

