// ListBudgets reads every budget record the filter keeps.
func ListBudgets(sandbox *api.Sandbox, self *ErpDb, filter BudgetFilter) ([]BudgetRecord, error) {
	collection, err := sandbox.Deps.OpinionatedAgnosDatabase.Collection(self.database, "budget")
	if err != nil {
		return nil, err
	}
	records, failure := collection.ListAll()
	if failure != nil {
		return nil, sandbox.Deps.OpinionatedAgnosDatabase.Fail(failure)
	}
	kept := []BudgetRecord{}
	for _, record := range records {
		built, err := buildBudgetRecord(sandbox, record)
		if err != nil {
			return nil, err
		}
		if !matchBudget(sandbox, built, filter) {
			continue
		}
		kept = append(kept, built)
	}
	return kept, nil
}

// ListBudgetsPage reads up to limit budget records after the first offset, every one past them when limit is 0.
func ListBudgetsPage(sandbox *api.Sandbox, self *ErpDb, offset int, limit int) ([]BudgetRecord, error) {
	collection, err := sandbox.Deps.OpinionatedAgnosDatabase.Collection(self.database, "budget")
	if err != nil {
		return nil, err
	}
	records, failure := collection.List(offset+1, limit)
	if failure != nil {
		return nil, sandbox.Deps.OpinionatedAgnosDatabase.Fail(failure)
	}
	page := []BudgetRecord{}
	for _, record := range records {
		built, err := buildBudgetRecord(sandbox, record)
		if err != nil {
			return nil, err
		}
		page = append(page, built)
	}
	return page, nil
}

